local _, A = ...
A.Tooltips = {[99]={["m"]={"Instant","30 sec cooldown","Requires Druid"},["d"]="Shift into Bear Form and invoke the spirit of Ursol to let loose a deafening roar, incapacitating all enemies within 10 yards for 3 sec. Damage may cancel the effect.",["pt"]={["n"]="Rugido Incapacitante",["m"]={"Instantâneo","30 seg de recarga","Requer Druida"},["d"]="Assume a Forma de Urso e evoca o espírito de Ursol para soltar um rugido ensurdecedor, incapacitando todos os inimigos em um raio de 10 m por 3 s. Dano pode cancelar o efeito."}},[118]={["m"]={"4% of base mana","30 yd range","1.7 sec cast","Requires Mage"},["d"]="Transforms the enemy into a sheep, wandering around incapacitated for 1 min. While affected, the victim cannot take actions but will regenerate health very quickly. Damage may cancel the effect. Limit 1.\nOnly works on Beasts, Humanoids and Critters. Glyph of Crittermorph: When critters are affected, can affect multiple targets, and has a duration of 1 day",["pt"]={["n"]="Polimorfia",["m"]={"4% de base mana","Alcance de 30m","1.7 seg de lançamento","Requer Mago"},["d"]="Transforma o inimigo em ovelha, fazendo com que perambule incapacitado por 1 min. Enquanto estiver afetada, a vítima não pode realizar nenhuma ação, mas seus pontos de vida se regeneram rapidamente. Dano pode cancelar o efeito. Limite de 1.\nSó funciona em Feras, Humanoides e Bichos. Glifo de Bichomorfose: Quando bichos são afetados, o efeito pode afetar vários alvos e tem duração de 1 dia"}},[122]={["m"]={"2% of base mana","Instant","30 sec cooldown","Requires Mage"},["d"]="Blasts enemies within 12 yds of you for (5.149% of Spell Power) Frost damage and freezes them in place for 6 sec. Damage may interrupt the freeze effect.",["pt"]={["n"]="Nova Congelante",["m"]={"2% de base mana","Instantâneo","30 seg de recarga","Requer Mago"},["d"]="Atinge inimigos em um raio de 12 m de você, causando de dano de Gelo e congelando-os por até 6 s. Dano pode interromper o efeito de congelamento."}},[370]={["m"]={"14% of base mana","30 yd range","Instant","Requires Shaman"},["d"]="Purges the enemy target, removing 1 beneficial Magic effect.",["pt"]={["n"]="Expurgar",["m"]={"14% de base mana","Alcance de 30m","Instantâneo","Requer Xamã"},["d"]="Expurga o alvo inimigo, removendo 1 efeito mágico benéfico."}},[408]={["m"]={"25 Energy / 1 to 5 Combo Points","Melee Range","Instant","30 sec cooldown","Requires Rogue"},["d"]="Requires Melee Weapon Finishing move that stuns the target. Lasts longer per combo point, up to 8 sec: 1 point: 4 seconds 2 points: 5 seconds 3 points: 6 seconds 4 points: 7 seconds 5 points: 8 seconds",["pt"]={["n"]="Golpe no Rim",["m"]={"25 de Energia / 1 para 5 Pontos de Combo","Alcance corpo a corpo","Instantâneo","30 seg de recarga","Requer Ladino"},["d"]="Requer Arma corpo a corpo Golpe final que atordoa o alvo. Dura de acordo com a quantidade de pontos de combo, até 8 s: 1 ponto: 4 s 2 pontos: 5 s 3 pontos: 6 s 4 pontos: 7 s 5 pontos: 8 s"}},[475]={["m"]={"1.3% of base mana","40 yd range","Instant","8 sec cooldown","Requires Mage"},["d"]="Removes all Curses from a friendly target.",["pt"]={["n"]="Remover Maldição",["m"]={"1.3% de base mana","Alcance de 40m","Instantâneo","8 seg de recarga","Requer Mago"},["d"]="Remove todas as maldições do alvo aliado."}},[498]={["m"]={"0.7% of base mana","Instant","1 min cooldown","Requires Paladin"},["d"]="Reduces all damage you take by 20% for 8 sec. Usable while stunned.",["pt"]={["n"]="Proteção Divina",["m"]={"0.7% de base mana","Instantâneo","1 min de recarga","Requer Paladino"},["d"]="Reduz em 20% todo o dano recebido por 8 s. Pode ser usado sob atordoamento."}},[586]={["m"]={"Instant","30 sec cooldown","Requires Priest"},["d"]="Fade out, removing all your threat and reducing enemies' detection range against you for 10 sec.",["pt"]={["n"]="Desvanecer",["m"]={"Instantâneo","30 seg de recarga","Requer Sacerdote"},["d"]="Você desvanece, removendo toda a sua ameaça e reduzindo o alcance de detecção dos inimigos contra você por 10 s."}},[633]={["m"]={"40 yd range","Instant","10 min cooldown","Requires Paladin"},["d"]="Heals a friendly target for an amount equal to 100% your maximum health.\nCannot be used on a target with Forbearance. Causes Forbearance for 30 sec.",["pt"]={["n"]="Impor as Mãos",["m"]={"Alcance de 40m","Instantâneo","10 min de recarga","Requer Paladino"},["d"]="Concede cura a um alvo aliado equivalente a 100% do seu máximo de pontos de vida.\nNão é possível usar em alvos com Abstinência. Causa Abstinência por 30 s."}},[642]={["m"]={"Instant","5 min cooldown","Requires Paladin"},["d"]="Grants immunity to all damage, harmful effects, knockbacks and forced movement effects for 8 sec.\nCannot be used if you have Forbearance. Causes Forbearance for 30 sec.",["pt"]={["n"]="Escudo Divino",["m"]={"Instantâneo","5 min de recarga","Requer Paladino"},["d"]="Concede imunidade a todos os efeitos de dano, nocivos, de repulsão e de movimentação forçada por 8 s.\nNão pode ser usado se você tiver Abstinência. Causa Abstinência por 30 s."}},[702]={["m"]={"1% of base mana","40 yd range","Instant","Requires Warlock"},["d"]="Increases the time between an enemy's attacks by 20% for 2 min.\nCurses: A warlock can only have one Curse active per target.",["pt"]={["n"]="Maldição da Fraqueza",["m"]={"1% de base mana","Alcance de 40m","Instantâneo","Requer Bruxo"},["d"]="Aumenta em 20% o intervalo entre ataques do inimigo por 2 min.\nMaldições: um bruxo só pode ter uma maldição ativa por alvo."}},[710]={["m"]={"1.5% of base mana","30 yd range","1.5 sec cast","Requires Warlock"},["d"]="Banishes an enemy Demon, Aberration Greater Banish: Undead, or Elemental, preventing any action for 30 sec. Limit 1. Casting Banish again on the target will cancel the effect.",["pt"]={["n"]="Banir",["m"]={"1.5% de base mana","Alcance de 30m","1.5 seg de lançamento","Requer Bruxo"},["d"]="Bane um Demônio, Aberração Banimento Maior: Morto-vivo ou Elemental inimigo, impedindo-o de agir durante 30 s. Limite de 1. Lançar Banir novamente no mesmo alvo cancela o efeito."}},[740]={["m"]={"3.68% of base mana","Channeled (6 sec cast)","3 min cooldown","Requires Druid"},["d"]="Heals all allies within 40 yards for over 6 sec. Flourish: Extends the duration of all your heal over time effects by 2 sec every 1 sec Healing decreased beyond 5 targets.\nRoots form around you while channeling, absorbing up to 60% of your health in damage and preventing knockbacks.",["pt"]={["n"]="Tranquilidade",["m"]={"3.68% de base mana","Canalizado (6 seg de lançamento)","3 min de recarga","Requer Druida"},["d"]="Cura pontos de vida de todos os aliados em um raio de 40 m ao longo de 6 s. Florescer: Prolonga em 2 s a duração dos seus efeitos de cura periódica a cada 1 s Cura reduzida acima de 5 alvos.\nFormam-se raízes ao seu redor durante a canalização, absorvendo até 60% dos seus pontos de vida em dano e evitando a repulsão."}},[781]={["m"]={"Unlimited range","Instant","20 sec cooldown","Requires Hunter"},["d"]="Leap backwards Posthaste: clearing movement impairing effects, and increasing your movement speed by 0% for 4 sec Narrow Escape: and activating a web trap which encases all targets within 8 yards in sticky webs, preventing movement for 8 sec.",["pt"]={["n"]="Desvencilhar",["m"]={"Alcance ilimitado","Instantâneo","20 seg de recarga","Requer Caçador"},["d"]="Salta para trás O Quanto Antes: livrando-se de efeitos que prejudicam o movimento e aumentando em 0% a velocidade de movimento por 4 s Fuga por Pouco: e ativando uma armadilha de teias que prende todos os alvos em um raio de 8 metros e impede o movimento por 8 s."}},[853]={["m"]={"0.7% of base mana","10 yd range","Instant","45 sec cooldown","Requires Paladin"},["d"]="Stuns the target for 6 sec.",["pt"]={["n"]="Martelo da Justiça",["m"]={"0.7% de base mana","Alcance de 10m","Instantâneo","45 seg de recarga","Requer Paladino"},["d"]="Atordoa o alvo por 6 s."}},[871]={["m"]={"Instant","3 min cooldown","Requires Warrior"},["d"]="Reduces all damage you take by 40% for 8 sec.",["pt"]={["n"]="Muralha de Escudos",["m"]={"Instantâneo","3 min de recarga","Requer Guerreiro"},["d"]="Reduz em 40% todo o dano recebido por 8 s."}},[1022]={["m"]={"3% of base mana","40 yd range","Instant","5 min cooldown","Requires Paladin"},["d"]="Blesses a party or raid member, granting immunity to Physical damage and harmful effects for 10 sec.\nCannot be used on a target with Forbearance. Causes Forbearance for 30 sec.",["v"]={{["s"]={"Holy","Retribution"},["d"]="Blesses a party or raid member, granting immunity to Physical damage and harmful effects for 10 sec.\nCannot be used on a target with Forbearance. Causes Forbearance for 30 sec."},{["s"]={"Protection"},["d"]="Blesses a party or raid member, granting immunity to Physical damage and harmful effects for 10 sec.\nCannot be used on a target with Forbearance. Causes Forbearance for 30 sec.\nShares a cooldown with Blessing of Spellwarding."}},["pt"]={["n"]="Bênção de Proteção",["m"]={"3% de base mana","Alcance de 40m","Instantâneo","5 min de recarga","Requer Paladino"},["d"]="Abençoa um integrante do grupo ou raide, protegendo-o de dano Físico e efeitos nocivos por 10 s.\nNão pode ser usado em alvos com Abstinência. Causa Abstinência por 30 s.",["v"]={{["d"]="Abençoa um integrante do grupo ou raide, protegendo-o de dano Físico e efeitos nocivos por 10 s.\nNão pode ser usado em alvos com Abstinência. Causa Abstinência por 30 s."},{["d"]="Abençoa um integrante do grupo ou raide, protegendo-o de dano Físico e efeitos nocivos por 10 s.\nNão pode ser usado em alvos com Abstinência. Causa Abstinência por 30 s.\nCompartilha a recarga com Bênção de Proteção Mágica."}}}},[1044]={["m"]={"1.4% of base mana","40 yd range","Instant","25 sec cooldown","Requires Paladin"},["d"]="Blesses a party or raid member, granting immunity to movement impairing effects Unbound Freedom: and increasing movement speed by 30%for 8 sec.",["pt"]={["n"]="Bênção da Liberdade",["m"]={"1.4% de base mana","Alcance de 40m","Instantâneo","25 seg de recarga","Requer Paladino"},["d"]="Abençoa um integrante do grupo ou raide, concedendo imunidade a efeitos que dificultam o movimento Liberdade dos Desvinculados: e aumentando em 30% a velocidade de movimentopor 8 s."}},[1122]={["m"]={"2% of base mana","30 yd range","Instant","2 min cooldown","Requires Warlock"},["d"]="Summons an Infernal from the Twisting Nether, impacting for (60% of Spell Power) Fire damage and stunning all enemies in the area for 2 sec.\nThe Infernal will serve you for 30 sec, dealing damage to all nearby enemies every 2 sec and generating 1 Soul Shard Fragment every 1 sec.",["pt"]={["n"]="Evocar Infernal",["m"]={"2% de base mana","Alcance de 30m","Instantâneo","2 min de recarga","Requer Bruxo"},["d"]="Evoca um Infernal da Espiral Etérea, causando de dano de Fogo com o impacto e atordoando todos os alvos inimigos na área por 2 s.\nO Infernal ficará às suas ordens por 30 s, causando de dano a todos os inimigos próximos a cada 2 s e gerando 1 Fragmento de Estilhaço de Alma a cada 1 s."}},[1160]={["m"]={"Instant","45 sec cooldown","Requires Warrior"},["d"]="Morale Killer: Demoralizes all enemies within 10 yards, reducing the damage they do by 25% for 8 sec / Demoralizes all enemies within 10 yards, reducing the damage they deal to you by 20% for 8 sec. Booming Voice: Generates 0 Rage.",["pt"]={["n"]="Brado Desmoralizador",["m"]={"Instantâneo","45 seg de recarga","Requer Guerreiro"},["d"]="Assassino do Moral: Desmoraliza todos os inimigos em um raio de 10 m, reduzindo em 25% o dano que eles causam por 8 s / Desmoraliza todos os inimigos em um raio de 10 m, reduzindo em 20% o dano que causam a você por 8 s. Voz Estrondosa: Gera de 0 Raiva."}},[1714]={["m"]={"1% of base mana","40 yd range","Instant","Requires Warlock"},["d"]="Forces the target to speak in Demonic, increasing the casting time of all spells by 30% for 1 min.\nCurses: A warlock can only have one Curse active per target.",["pt"]={["n"]="Maldição de Línguas",["